using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.Rendering;using TechnifyERP.Application.Notes;
namespace TechnifyERP.Areas.Student.Controllers;
[Area("Student"),Authorize(Roles="Student")]public sealed class NotesController(INoteService service):Controller{public async Task<IActionResult>Index(CancellationToken ct){ViewBag.Courses=(await service.GetCoursesAsync(UserId,ct)).Select(x=>new SelectListItem($"{x.Code} - {x.Name}",x.Id.ToString()));return View(await service.GetAsync(UserId,ct));}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Save(int id,int? courseId,string title,string content,CancellationToken ct){var r=id==0?await service.CreateAsync(UserId,courseId,title,content,ct):await service.UpdateAsync(UserId,id,courseId,title,content,ct);TempData[r==NoteActionResult.Success?"SuccessMessage":"ErrorMessage"]=r==NoteActionResult.Success?"Note save ho gayi.":"Note details valid nahi.";return RedirectToAction(nameof(Index));}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Delete(int id,CancellationToken ct){await service.DeleteAsync(UserId,id,ct);return RedirectToAction(nameof(Index));}private string UserId=>User.FindFirstValue(ClaimTypes.NameIdentifier)!;}
